style.css:
@-moz-document domain("wiki.siriusmc.net") {
/* Swap these values to customize the colors */
    :root {
        --my-background: #121212;
        --my-panel: #1e1e1e;
        --my-secondary: #292929;
        --my-text: #dedede;
        --my-heading: #f0f0f0;
        --my-muted: #aaaaaa;
        --my-border: #383838;
        --my-link: #81b4ff;
        --my-hover: #b4d4ff;
        --my-purple-heading: #c9a0ed;
        --my-purple-button: #dda0df;
        --my-purple-border: #805080;
        --my-purple-background: #352938;
        --my-description: #cccccc;
    }

    /* Main background */
    html,
    body,
    #content {
        color-scheme: dark !important;
        background-color: var(--my-background) !important;
        color: var(--my-text) !important;
    }

    /* Header */
    header#header {
        background-color: var(--my-panel) !important;
        border-bottom: 1px solid var(--my-border) !important;
    }

    /* Content panels */
    .card,
    .grid-card,
    .content-wrap,
    .page-content-wrap,
    .page-content {
        background-color: var(--my-panel) !important;
        color: var(--my-text) !important;
        border-color: var(--my-border) !important;
    }

    /* Headings */
    h1, h2, h3, h4, h5, h6 {
        color: var(--my-heading) !important;
    }

    /* Links */
    a {
        color: var(--my-link) !important;
    }

    a:hover {
        color: var(--my-hover) !important;
    }

    /* Navigation and listings */
    .entity-list-item,
    .sidebar-page-nav,
    .breadcrumbs {
        color: var(--my-text) !important;
        border-color: var(--my-border) !important;
    }

    .entity-list-item:hover {
        background-color: var(--my-secondary) !important;
    }

    /* Search and input fields */
    input,
    textarea,
    select {
        background-color: var(--my-secondary) !important;
        color: var(--my-text) !important;
        border-color: var(--my-border) !important;
    }

    input::placeholder {
        color: var(--my-muted) !important;
    }

    /* Tables */
    table,
    th,
    td {
        background-color: var(--my-panel) !important;
        color: var(--my-text) !important;
        border-color: var(--my-border) !important;
    }

    th,
    tr:nth-child(even) td {
        background-color: var(--my-secondary) !important;
    }

    /* Custom purple headings */
    p[style*="color:#473355"],
    p[style*="color: #473355"],
    p[style*="rgb(71, 51, 85)"] {
        color: var(--my-purple-heading) !important;
    }

    /* Custom gray descriptions */
    p[style*="color:#666"],
    p[style*="color: #666"],
    p[style*="rgb(102, 102, 102)"] {
        color: var(--my-description) !important;
    }

    /* Custom purple buttons */
    a span[style*="color:#7b3d7b"],
    a span[style*="color: #7b3d7b"],
    a span[style*="rgb(123, 61, 123)"] {
        color: var(--my-purple-button) !important;
        background-color: var(--my-purple-background) !important;
        border-color: var(--my-purple-border) !important;
    }

    /* Custom purple button hover effect */
    a:hover span[style*="color:#7b3d7b"],
    a:hover span[style*="color: #7b3d7b"],
    a:hover span[style*="rgb(123, 61, 123)"] {
        color: #f5d5ff !important;
        background-color: #503550 !important;
        border-color: var(--my-purple-button) !important;
    }

    /* Code blocks */
    pre,
    code {
        background-color: var(--my-secondary) !important;
        color: var(--my-text) !important;
        border-color: var(--my-border) !important;
    }

    /* Horizontal separators */
    hr {
        background-color: var(--my-border) !important;
        border-color: var(--my-border) !important;
    }

    /* Scrollbars */
    html {
        scrollbar-color: #484848 #121212 !important;
    }
}
